import 'dart:async';import 'package:flutter_test/flutter_test.dart';
import 'package:flutter_core/shell_utilities/shell_utilities_controller.dart';import 'package:flutter_core/preference_sync.dart';
class Cache implements PreferenceCache {final values=<String,String>{};@override Future<String?> read(String k)async=>values[k];@override Future<void> write(String k,String v)async{values[k]=v;}@override Future<void> remove(String k)async{values.remove(k);}}
final scope=PreferenceScope('t','u','psw','live');
Map<String,Object?> item({bool read=false,String id='record1'})=>{'id':id,'title':'Notice','detail':'Authorized content','read':read,'status':'delivered'};
ShellUtilitiesController make([Map<String,UtilityPort> ports=const {}])=>ShellUtilitiesController(scope:scope,favourites:PreferenceSyncClient(binding:PreferenceBinding(scope:scope,kind:'shortcuts',resource:'navigation',screenIds:['1','2']),cache:Cache(),transport:(r)async=>{'version':1,'scope':scope.toJson(),'kind':'shortcuts','resource':'navigation','revision':r['action']=='read'?0:1,'document':r['action']=='read'?null:r['document']}),destinations:[UtilityDestination('1','Calendar','Events'),UtilityDestination('2','Notes','Owned',disabled:true)],navigate:(_){},ports:ports);
void main(){
 test('missing adapters and errors never produce fake ready empty state',()async{final c=make({'events':UtilityPort(load:()async=>throw StateError('denied'))});await c.load('notes');expect(c.current['notes']!.status,'unavailable');await c.load('events');expect(c.current['events']!.status,'error');c.dispose();});
 test('read/unread requires server acknowledgement and preserves failed value',()async{var allowed=false;final c=make({'notifications':UtilityPort(load:()async=>[item()],markRead:(id,read)async{if(!allowed)throw StateError('denied');return item(id:id,read:read);})});await c.load('notifications');await c.markRead('notifications','record1',true);expect(c.current['notifications']!.items.single.read,false);allowed=true;await c.markRead('notifications','record1',true);expect(c.current['notifications']!.items.single.read,true);await c.markRead('notifications','record1',false);expect(c.current['notifications']!.items.single.read,false);c.dispose();});
 test('schema identity and disabled shortcuts fail closed',()async{final c=make({'notifications':UtilityPort(load:()async=>[item()],markRead:(_,_)async=>item(id:'other',read:true))});await c.load('notifications');await c.markRead('notifications','record1',true);expect(c.current['notifications']!.status,'error');expect(c.current['notifications']!.items.single.read,false);expect(()=>utilityItems([item(),item()]),throwsFormatException);expect(()=>utilityItems([{...item(),'route':'/admin'}]),throwsFormatException);await expectLater(c.toggle('2'),throwsStateError);expect(()=>c.open('99'),throwsStateError);c.dispose();});
 test('search favourites and saving inherit account preference state',()async{final c=make();await c.favourites.load();expect(c.search('events').single.id,'1');await c.toggle('1');expect(c.favourites.current['draft'],{'version':1,'screenIds':['1']});await c.favourites.save();expect(c.favourites.current['status'],'clean');c.dispose();});
 test('disposed actor ignores pending resource completion',()async{final pending=Completer<Object?>(),c=make({'notes':UtilityPort(load:()=>pending.future)}),loading=c.load('notes');c.dispose();pending.complete([item()]);await loading;expect(c.current,isEmpty);await expectLater(c.toggle('1'),throwsStateError);});
}
